// The firehose is far larger than anything worth labelling one call at a
// time, so take a fixed share of it. Bucketing on the post's own identity
// keeps the choice deterministic: the same post is always kept or always
// dropped, which is what lets a replayed batch produce the same rows.
const ONE_IN = 40;
function bucket(text) {
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) % ONE_IN;
}
export default (rows) => rows
  .filter((r) => r.lang === 'en' && r.text.length >= 80 && bucket(r.uri) === 0)
  .map((r) => ({
    uri: r.uri,
    author: r.author,
    posted_at: r.posted_at,
    text: r.text.length > 400 ? r.text.slice(0, 400) : r.text
  }))
